    group by c0.KEY_HASH
) w071 on src.PARENT_KEY_HASH = w071._JK071
left join (
    select
        c0.KEY_HASH as _JK072,
        count(*) as _N072,
        max(d0.MEMBER_CODE) as _V072
    from {{ ref('hop_uwr_memd_tab') }} c0
    join {{ ref('stg_uwr_memd_tab_member_data') }} d0
